RMS master data export is needed using a MySQL query, segment-wise and for all levels.

RMS master data export currently includes all hierarchy levels by default. However, we need to modify this so that export only includes data for segments allowed to the user.

*Requirements:*

* By default, export should include ALL-ALL levels for each category.
* Segment-wise export should include all levels for respective exchange. For example, if NSE EQ is allowed, then NSE-ALL level should also be included in export, and same applies for other exchanges.
* Find below SQL query provided from our end to Socgen, 
* [^Revised_Query_RMS MasterDump_2.sql]  



Please check below updated query,

h6. {color:#0747a6}SELECT{color}
{color:#0747a6}    rs.userid AS "User ID",{color}
{color:#0747a6}    CASE rs.exchange{color}
{color:#0747a6}        WHEN -1 THEN 'ALL'{color}
{color:#0747a6}        WHEN  1 THEN 'NSE'{color}
{color:#0747a6}        WHEN  2 THEN 'BSE'{color}
{color:#0747a6}        WHEN  5 THEN 'NSE-CURRENCY'{color}
{color:#0747a6}        ELSE 'UNKNOWN'{color}
{color:#0747a6}    END AS "Exchanges",{color}
{color:#0747a6}    CASE rs.segment{color}
{color:#0747a6}        WHEN -1 THEN 'ALL'{color}
{color:#0747a6}        WHEN  1 THEN 'EQUITY'{color}
{color:#0747a6}        WHEN  2 THEN 'FUTURE'{color}
{color:#0747a6}        WHEN  4 THEN 'OPTIONS'{color}
{color:#0747a6}        WHEN  5 THEN 'SLBM'{color}
{color:#0747a6}        ELSE 'UNKNOWN'{color}
{color:#0747a6}    END AS "Segment",{color}
{color:#0747a6}    rs.single_order_qty          AS "Single Order Qty",{color}
{color:#0747a6}    rs.single_order_value        AS "Single Order Value",{color}
{color:#0747a6}    rs.pending_total_qty         AS "Pending Total Quantity",{color}
{color:#0747a6}    rs.pending_buy_qty           AS "Pending Buy Quantity",{color}
{color:#0747a6}    rs.pending_sell_qty          AS "Pending Sell Quantity",{color}
{color:#0747a6}    rs.pending_total_value       AS "Pending Total Value",{color}
{color:#0747a6}    rs.pending_buy_value         AS "Pending Buy Value",{color}
{color:#0747a6}    rs.pending_sell_value        AS "Pending Sell Value",{color}
{color:#0747a6}    rs.quantity_net_qty          AS "Net Quantity",{color}
{color:#0747a6}    rs.quantity_buy_qty          AS "Buy Quantity",{color}
{color:#0747a6}    rs.quantity_sell_qty         AS "Sell Quantity",{color}
{color:#0747a6}    rs.exposure_net_limit        AS "Net Limit",{color}
{color:#0747a6}    rs.exposure_buy_limit        AS "Buy Limit",{color}
{color:#0747a6}    rs.exposure_sell_limit       AS "Sell Limit",{color}
{color:#0747a6}    rs.exposure_turnover_limit   AS "Turnover Limit",{color}
{color:#0747a6}    rs.spread_single_order_qty   AS "Spread Single Order Qty",{color}
{color:#0747a6}    rs.spread_single_order_value AS "Spread Single Order Value",{color}
{color:#0747a6}    rs.orders_per_sec            AS "Orders Per Sec",{color}
{color:#0747a6}    rs.orders_state              AS "Orders State",{color}
{color:#0747a6}    CASE rs.netlimit_stk_idx{color}
{color:#0747a6}        WHEN FALSE THEN '0'{color}
{color:#0747a6}        WHEN TRUE  THEN '1'{color}
{color:#0747a6}        ELSE 'UNKNOWN'{color}
{color:#0747a6}    END AS "Gross STK/IDX",{color}
{color:#0747a6}    rs.exposure_limit_idx        AS "Gross Expos IDX",{color}
{color:#0747a6}    CASE rs.applyitmrule  {color}
{color:#0747a6}        WHEN FALSE THEN '0'{color}
{color:#0747a6}        WHEN TRUE  THEN '1'{color}
{color:#0747a6}        ELSE 'UNKNOWN'{color}
{color:#0747a6}    END AS "ApplyITMRule",{color}
{color:#0747a6}    rs.itmpercent                AS "ITMPercent",{color}
{color:#0747a6}    CASE rs.bismarketorder{color}
{color:#0747a6}        WHEN FALSE THEN '0'{color}
{color:#0747a6}        WHEN TRUE  THEN '1'{color}
{color:#0747a6}        ELSE 'UNKNOWN'{color}
{color:#0747a6}    END AS "MarketOrder",{color}
{color:#0747a6}    CASE ({color}
{color:#0747a6}        SELECT blimitinlacs{color}
{color:#0747a6}        FROM rms_general_settings{color}
{color:#0747a6}         ){color}
{color:#0747a6}        WHEN FALSE THEN '1'{color}
{color:#0747a6}        WHEN TRUE  THEN '0'{color}
{color:#0747a6}        ELSE 'UNKNOWN'{color}
{color:#0747a6}    END AS "ValuesInRsOrLacs",{color}
{color:#0747a6}   rs.dnetvalue                 AS "NetValue"{color}

h6. {color:#0747a6}FROM rms_surveillance rs{color}
{color:#0747a6}JOIN clientdetails cd{color}
{color:#0747a6}  ON cd.cgreekuserorinvestorid = rs.userid{color}
{color:#0747a6}WHERE rs.userid NOT IN ({color}
{color:#0747a6}    SELECT cgreekuserorinvestorid{color}
{color:#0747a6}    FROM clientdetails{color}
{color:#0747a6}    WHERE cuserstatus IN ('2', '4'){color}
{color:#0747a6}){color}
{color:#0747a6}AND ((cd.cmktallowed LIKE '%NSE EQ%' AND rs.exchange = 1 AND (rs.segment = 1 or rs.segment = -1)){color}
{color:#0747a6}OR (cd.cmktallowed LIKE '%NSE FO%' AND rs.exchange = 1 AND (rs.segment = 2 or rs.segment = 4 or rs.segment = -1)){color}
{color:#0747a6}OR (cd.cmktallowed LIKE '%NSE CD%' AND rs.exchange = 5 AND (rs.segment = 2 or rs.segment = 4 or rs.segment = -1)){color}
{color:#0747a6}OR (cd.cmktallowed LIKE '%NSE SLBM%' AND rs.exchange = 1 AND (rs.segment = 5 or rs.segment = -1)){color}
{color:#0747a6}OR (cd.cmktallowed LIKE '%BSE EQ%' AND rs.exchange = 2 AND (rs.segment = 1 or rs.segment = -1)){color}
{color:#0747a6}OR (cd.cmktallowed LIKE '%BSE FO%' AND rs.exchange = 2 AND (rs.segment = 2 or rs.segment = 4 or rs.segment = -1)){color}
{color:#0747a6}OR (rs.exchange = -1 AND (rs.segment = -1))){color}
{color:#0747a6}ORDER BY rs.exchange, rs.segment, rs.userid;{color}

