column41:
For NUMA implementation we can use following example.

Have to keep Producer/Consumer under gs::NUMA namespace on common location.

Keep numa_node  value as configurable.

Following readings taken by running following code:

h5. *With NUMA on same node:*
{color:#0747a6}Consumer read: 302249 from index 9  ==> Iteration 1{color}
{color:#0747a6}Consumer read: 299602 from index 2  ==> Iteration 2{color}
{color:#0747a6}Consumer read: 297962 from index 2  ==> Iteration 3{color}
{color:#0747a6}Consumer read: 314453 from index 3  ==> Iteration 4{color}
{color:#0747a6}Consumer read: 298282 from index 2  ==> Iteration 5{color}

h5. *With NUMA on different node(i.e. without NUMA):*
{color:#0747a6}Consumer read: 279112 from index 2  ==> Iteration 1{color}
{color:#0747a6}Consumer read: 282129 from index 9  ==> Iteration 2{color}
{color:#0747a6}Consumer read: 271730 from index 0  ==> Iteration 3{color}
{color:#0747a6}Consumer read: 281072 from index 2  ==> Iteration 4{color}
{color:#0747a6}Consumer read: 272460 from index 0  ==> Iteration 5{color}



#include <iostream>
#include <thread>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <numa.h>
#include <atomic>

// Define a shared buffer for producer-consumer
const int BUFFER_SIZE = 10;
std::atomic<int> buffer[BUFFER_SIZE];  // Shared buffer
std::atomic<int> write_index(0);       // Producer write index
std::atomic<int> read_index(0);        // Consumer read index

std::mutex mtx;
std::condition_variable cv_producer, cv_consumer;

bool stop_flag = false; // Flag to stop the producer and consumer threads

// Producer function: writes data to the buffer
void producer(int node) {
    if (numa_run_on_node(node) != 0) {
        std::cerr << "Failed to pin producer thread to NUMA node " << node << std::endl;
        return;
    }

{noformat}int value = 0;
while (!stop_flag) {
    // Wait until the buffer has space (i.e., space between write and read index)
    std::unique_lock<std::mutex> lock(mtx);
    cv_producer.wait(lock, [] {
        return (write_index.load() + 1) % BUFFER_SIZE != read_index.load();
    });

    // Write to the buffer
    buffer[write_index.load()] = value++;
    std::cout << "Producer wrote: " << value - 1 << " at index " << write_index.load() << std::endl;

    // Update write index and notify consumer
    write_index.store((write_index.load() + 1) % BUFFER_SIZE);
    cv_consumer.notify_one();
}{noformat}

}

// Consumer function: reads data from the buffer
void consumer(int node) {
    if (numa_run_on_node(node) != 0) {
        std::cerr << "Failed to pin consumer thread to NUMA node " << node << std::endl;
        return;
    }

{noformat}while (!stop_flag) {
    // Wait until there is data in the buffer (i.e., read index not equal to write index)
    std::unique_lock<std::mutex> lock(mtx);
    cv_consumer.wait(lock, [] {
        return write_index.load() != read_index.load();
    });

    // Read from the buffer
    int value = buffer[read_index.load()];
    std::cout << "Consumer read: " << value << " from index " << read_index.load() << std::endl;

    // Update read index and notify producer
    read_index.store((read_index.load() + 1) % BUFFER_SIZE);
    cv_producer.notify_one();
}{noformat}

}

int main() {
    // Check the number of NUMA nodes
    int num_nodes = numa_num_configured_nodes();
    std::cout << "Number of NUMA nodes: " << num_nodes << std::endl;

{noformat}// Pin producer and consumer threads to NUMA node 0 (assuming we want both on the same node)
int numa_node = 0;

// Create producer and consumer threads
std::thread producer_thread(producer, numa_node);
std::thread consumer_thread(consumer, numa_node);

// Run for some time (e.g., 5 seconds) then stop
std::this_thread::sleep_for(std::chrono::seconds(5));

stop_flag = true;  // Stop the threads

// Notify both threads to exit if they are waiting on condition variables
cv_producer.notify_all();
cv_consumer.notify_all();

// Join threads
producer_thread.join();
consumer_thread.join();

return 0;{noformat}

}

